namespace Fanex.Age.UI.TotalBets
{
    public partial class TotalGoal_Page : TotalBets_Page
    {
        #region Variable
        private string rowBgOdd = Fanex.Age.UI.Common.RowBgOdd;
        private string rowBgEven = Fanex.Age.UI.Common.RowBgEven;
        private string rowBgClosed = Fanex.Age.UI.Common.RowBgClosed;
        #endregion

        #region Override

        public override void RenderContent(HtmlTextWriter writer)
        {
            var darkModeName = DarkModeHelper.GetDarkModeName(CurrentUserSession);
            if (!string.IsNullOrWhiteSpace(darkModeName))
            {
                rowBgOdd = DarkModeColor.RowBgOdd;
                rowBgEven = DarkModeColor.RowBgEven;
                rowBgClosed = DarkModeColor.RowBgClosed;
            }

            DataTable totalGoalList = View as DataTable;

            TotalGoal_Template tpl = new TotalGoal_Template();
            tpl.DarkModeName = darkModeName;
            tpl.Contents.TotalGoalContent.Clear();

            if (!Sunplus.Agent.Model.BL.Definitions.AppSettings.PiwikEnable)
            {
                tpl.Piwik.Clear();
            }
            
            int counter = 0;
            if (totalGoalList.Rows.Count > 0)
            {
                tpl.Contents.NotFoundContent.Hide();

                TotalGoal_Contents_TotalGoalContent_Block contentBlock = new TotalGoal_Contents_TotalGoalContent_Block();
                for (int i = 0; i < totalGoalList.Rows.Count; i++)
                {
                    DataRow dr = totalGoalList.Rows[i];

                    counter++;
                    if (totalGoalList.Columns.Contains("closed") && Convert.ToInt32(dr["closed"]) != 0)
                    {
                        contentBlock.ColorClass = rowBgClosed;
                    }
                    else
                    {
                        contentBlock.ColorClass = (counter % 2) == 0 ? rowBgEven : rowBgOdd;
                    }

                    contentBlock.ColorOver = Fanex.Age.UI.Common.RowBgOver;
                    contentBlock.ValueNo = counter.ToString();
                    contentBlock.ValueHome = CacheRef.GetTeamName(Convert.ToInt32(dr["homeid"])) + ((bool)dr["isNeutral"] ? Resources.Lang.IsNeutral : string.Empty);
                    contentBlock.ValueAway = CacheRef.GetTeamName(Convert.ToInt32(dr["awayid"]));

                    RenderFullTimeTotalGoal(contentBlock, dr);

                    RenderHalfTimeTotalGoal(contentBlock, dr);       

                    contentBlock.MatchId = dr["matchid"].ToString();

                    tpl.Contents.TotalGoalContent.Append(contentBlock);
                }
            }

            // Bet List Url
            tpl.BetListsUrl.BetListsUrl = MicroSites.BetListsUrl();

            if (_fullMode)
            {
                writer.Write(tpl);
            }
            else
            {
                writer.Write(tpl.Contents);
            }   
        }

        private static void RenderHalfTimeTotalGoal(TotalGoal_Contents_TotalGoalContent_Block contentBlock, DataRow dr)
        {
            if (Convert.ToInt16(dr["betcount_126"]) != 0)
            {
                contentBlock.Value1H01 = TotalGoalRoundColor(dr["126_total01"]);
                contentBlock.Value1H23 = TotalGoalRoundColor(dr["126_total23"]);
                contentBlock.Value1H4Over = TotalGoalRoundColor(dr["126_total4over"]);
            }
            else
            {
                contentBlock.Value1H01 = string.Empty;
                contentBlock.Value1H23 = string.Empty;
                contentBlock.Value1H4Over = string.Empty;
            }
        }

        private static void RenderFullTimeTotalGoal(TotalGoal_Contents_TotalGoalContent_Block contentBlock, DataRow dr)
        {
            if (Convert.ToInt16(dr["betcount_6"]) != 0)
            {
                contentBlock.Value01 = TotalGoalRoundColor(dr["6_total01"]);
                contentBlock.Value23 = TotalGoalRoundColor(dr["6_total23"]);
                contentBlock.Value46 = TotalGoalRoundColor(dr["6_total46"]);
                contentBlock.Value7Over = TotalGoalRoundColor(dr["6_total7over"]);
            }
            else
            {
                contentBlock.Value01 = string.Empty;
                contentBlock.Value23 = string.Empty;
                contentBlock.Value46 = string.Empty;
                contentBlock.Value7Over = string.Empty;
            }
        }

        public override object ValidateRequest(System.Collections.Hashtable p)
        {
            if (!CurrentUserSession.SubPageAccess.ViewTotalBets)
            {
                return new ErrorPage_Page(Resources.Lang.strNotAccessPage);
            }

            return null;
        }

        public override object InvokeData(System.Collections.Hashtable p)
        {
            return _TotalBetsBO.GetTotalGoal();
        }
        #endregion

        #region Utility
        /// <summary>
        /// Round color for total goal
        /// </summary>
        /// <param name="number"></param>
        /// <returns></returns>
        private static string TotalGoalRoundColor(object number)
        {
            decimal num = Convert.ToDecimal(number);

            return num > 0 ? "<span class='text-red'>" + Formater.DecFormat(num, 0) + "</span>" : Formater.DecFormat(num, 0);
        }
        #endregion
    }
}
